CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,verified INTEGER DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS verify_tokens(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY,author_id INTEGER NOT NULL,body TEXT NOT NULL,source_url TEXT,source_label TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY,post_id INTEGER NOT NULL,author_id INTEGER NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(user_id INTEGER PRIMARY KEY,display_name TEXT NOT NULL,banned INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS reset_tokens(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS saved_items(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL,kind TEXT NOT NULL,symbol TEXT NOT NULL,value REAL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS saved_owner ON saved_items(user_id,kind);
CREATE TABLE IF NOT EXISTS post_labels(post_id INTEGER PRIMARY KEY,label TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reactions(user_id INTEGER NOT NULL,post_id INTEGER NOT NULL,PRIMARY KEY(user_id,post_id));
CREATE TABLE IF NOT EXISTS hidden_content(kind TEXT NOT NULL,target_id INTEGER NOT NULL,moderator_id INTEGER NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(kind,target_id));
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL,kind TEXT NOT NULL,target_id INTEGER NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,admin_id INTEGER NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,visitor TEXT,user_id INTEGER,event TEXT NOT NULL,path TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_date ON events(created_at,event);
CREATE TABLE IF NOT EXISTS limits(bucket TEXT NOT NULL,period TEXT NOT NULL,count INTEGER NOT NULL,PRIMARY KEY(bucket,period));
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL,message TEXT NOT NULL,source TEXT,observed_at TEXT,created_at TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS alert_state(item_id INTEGER PRIMARY KEY,above INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS feed_order ON posts(created_at);
CREATE INDEX IF NOT EXISTS comment_parent ON comments(post_id,id);

CREATE TABLE IF NOT EXISTS operation_runs(id INTEGER PRIMARY KEY,created_at TEXT NOT NULL,payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS operation_date ON operation_runs(created_at);
